// UpdatedAtNEQ applies the NEQ predicate on the "updated_at" field.
func UpdatedAtNEQ(v time.Time) predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(sql.FieldNEQ(FieldUpdatedAt, v))
}

