// HasSupplier applies the HasEdge predicate on the "supplier" edge.
func HasSupplier() predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SupplierTable, SupplierColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSupplierWith applies the HasEdge predicate on the "supplier" edge with a given conditions (other predicates).
func HasSupplierWith(preds ...predicate.Supplier) predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(func(s *sql.Selector) {
		step := newSupplierStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SupplierWithdrawal) predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SupplierWithdrawal) predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SupplierWithdrawal) predicate.SupplierWithdrawal {
	return predicate.SupplierWithdrawal(sql.NotPredicates(p))
}
